## solution

#### dynamic programming with memoization

```cpp
#include <unordered_map>
#include <string>

int breakingBoundaries(int m, int n, int k, int r, int c, std::unordered_map<std::string, int> &memo) {
  std::string key = std::to_string(k) + "," + std::to_string(r) + "," + std::to_string(c);

  if (memo.count(key) > 0) {
    return memo[key];
  }

  if (r < 0 || r >= m || c < 0 || c >= n) {
    return 1;
  }

  if (k == 0) {
    return 0;
  }

  memo[key] = breakingBoundaries(m, n, k - 1, r + 1, c, memo) + 
    breakingBoundaries(m, n, k - 1, r - 1, c, memo) +
    breakingBoundaries(m, n, k - 1, r, c - 1, memo) +
    breakingBoundaries(m, n, k - 1, r, c + 1, memo);

  return memo[key];
}


int breakingBoundaries(int m, int n, int k, int r, int c) {
  std::unordered_map<std::string, int> memo;
  return breakingBoundaries(m, n, k , r, c, memo);
}
```

- m = # rows
- n = # columns
- k = # moves
- Time: O(mnk)
- Space: O(mnk)
